// Turns raw HTML into stable, comparable text and fingerprints it.
// Uses a dependency-free FNV-1a variant so the node works on any n8n instance.

// TEMPORARY TEST SWITCH — set back to '' before submitting the template.
// Any URL containing this string is treated as fully changed, which forces
// the AI branch to run on the very next execution.
const FORCE_CHANGE_FOR = 'n8n.io/pricing';

const page = $('Loop Over Tracked Pages').first().json;
const response = $input.first().json;

function fingerprint(str) {
  let a = 0x811c9dc5;
  let b = 0x01000193;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    a = Math.imul(a ^ c, 16777619) >>> 0;
    b = Math.imul(b ^ (c + i), 2166136261) >>> 0;
  }
  return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
}

function toReadableText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|h[1-6]|tr|section|article|header|footer)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .split('\n')
    .map((line) => line.replace(/[ \t\u00a0]+/g, ' ').trim())
    .filter((line) => line.length > 1)
    .join('\n');
}

const forced = FORCE_CHANGE_FOR !== '' && String(page.url || '').includes(FORCE_CHANGE_FOR);

// Forcing also blanks the previous text so the diff is large and the model
// has something real to score, instead of an empty delta.
const previousText = forced ? '' : String(page.last_snapshot || '');
const previousHash = String(page.last_hash || '');

// A failed fetch must never overwrite a good snapshot with nothing.
if (response.error || typeof response.data !== 'string' || response.data.length === 0) {
  return [{
    json: {
      url: page.url,
      name: page.name || page.url,
      status: 'fetch_failed',
      changed: false,
      text: String(page.last_snapshot || ''),
      hash: previousHash,
      previous_text: String(page.last_snapshot || ''),
      significance: 0,
      headline: 'Could not reach this page',
    },
  }];
}

const text = toReadableText(response.data);
const hash = fingerprint(text);
const isFirstRun = previousHash === '';

return [{
  json: {
    url: page.url,
    name: page.name || page.url,
    status: forced ? 'changed' : (isFirstRun ? 'baseline_stored' : (hash === previousHash ? 'unchanged' : 'changed')),
    changed: forced || (!isFirstRun && hash !== previousHash),
    text,
    hash,
    previous_text: previousText,
  },
}];

// Reduces the page to only the lines that appeared or disappeared,
// so the model reads a small delta instead of a whole page.

const current = $input.first().json;
const config = $('Set Monitor Configurations').first().json;
const maxLines = Number(config.max_diff_lines) || 40;

const split = (value) => String(value || '')
  .split('\n')
  .map((line) => line.trim())
  .filter(Boolean);

const previousLines = split(current.previous_text);
const currentLines = split(current.text);

const previousSet = new Set(previousLines);
const currentSet = new Set(currentLines);

const added = currentLines.filter((line) => !previousSet.has(line)).slice(0, maxLines);
const removed = previousLines.filter((line) => !currentSet.has(line)).slice(0, maxLines);

return [{
  json: {
    ...current,
    added_lines: added,
    removed_lines: removed,
    added_count: added.length,
    removed_count: removed.length,
    diff_text: [
      added.length ? 'ADDED:\n' + added.map((l) => '+ ' + l).join('\n') : 'ADDED:\n(nothing)',
      removed.length ? 'REMOVED:\n' + removed.map((l) => '- ' + l).join('\n') : 'REMOVED:\n(nothing)',
    ].join('\n\n'),
  },
}];

// Folds the model's verdict back onto the page record.
// Accepts whatever shape the chat model returns - object, plain string, or
// JSON wrapped in markdown fences - so the model stays swappable.

const page = $('Create Change Differentials').first().json;
const raw = $input.first().json;

function extractPayload(input) {
  if (typeof input === 'string') return input;
  const parts = (container) =>
    container && Array.isArray(container.parts)
      ? container.parts.map((p) => p.text).join('')
      : null;
  const candidates = [
    input.output,
    input.text,
    input.response,
    input.message && input.message.content,
    parts(input.content),
    input.candidates && input.candidates[0] ? parts(input.candidates[0].content) : null,
    input.content,
  ];
  for (const value of candidates) {
    if (value && typeof value === 'object') return value;
    if (typeof value === 'string' && value.trim()) return value;
  }
  return JSON.stringify(input);
}

function parseVerdict(input) {
  const payload = extractPayload(input);
  if (payload && typeof payload === 'object') return payload;
  const cleaned = String(payload).replace(/```json/gi, '').replace(/```/g, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    const parsed = JSON.parse(cleaned.slice(start, end + 1));
    return parsed && parsed.significance !== undefined ? parsed : null;
  } catch (error) {
    return null;
  }
}

const parsed = parseVerdict(raw);

// A missed competitor move is worse than a noisy email, so an unreadable
// response still surfaces rather than being silently scored zero.
const verdict = parsed || {
  significance: 3,
  category: 'content',
  headline: 'Page changed (AI response could not be parsed)',
  summary: 'Review this page manually.',
  why_it_matters: '',
};

const clamp = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.min(5, Math.max(0, Math.round(n)));
};

return [{
  json: {
    url: page.url,
    name: page.name,
    status: 'changed',
    hash: page.hash,
    text: page.text,
    added_count: page.added_count,
    removed_count: page.removed_count,
    added_lines: page.added_lines,
    removed_lines: page.removed_lines,
    significance: clamp(verdict.significance),
    category: String(verdict.category || 'content'),
    headline: String(verdict.headline || 'Page content changed'),
    summary: String(verdict.summary || ''),
    why_it_matters: String(verdict.why_it_matters || ''),
    _parsed_ok: parsed !== null,
    _raw_keys: Object.keys(raw),
  },
}];

// Filters to changes worth reading, ranks them, and renders the email.
// Outputs hasChanges so the next node can skip sending entirely.

// Accept either an aggregated { data: [...] } item or plain per-page items,
// so the node works with or without the Aggregate node in the path.
const items = $input.all();
const first = items.length ? items[0].json : {};
const results = Array.isArray(first.data) ? first.data : items.map((i) => i.json);

const config = $('Set Monitor Configurations').first().json;
const threshold = Number(config.significance_threshold) || 3;

const escapeHtml = (value) => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const significant = results
  .filter((row) => Number(row.significance) >= threshold)
  .sort((a, b) => Number(b.significance) - Number(a.significance));

const failed = results.filter((row) => row.status === 'fetch_failed');

if (significant.length === 0) {
  return [{
    json: {
      hasChanges: false,
      checked: results.length,
      subject: '',
      html: '',
      _debug_inputKeys: Object.keys(first),
      _debug_dataIsArray: Array.isArray(first.data),
      _debug_rowCount: results.length,
      _debug_significances: results.map((r) => r.significance),
      _debug_types: results.map((r) => typeof r.significance),
      _debug_threshold: threshold,
      _debug_firstRow: results[0] || null,
    },
  }];
}

const badge = (score) => {
  const color = score >= 5 ? '#dc2626' : score >= 4 ? '#ea580c' : '#ca8a04';
  const background = score >= 5 ? '#fef2f2' : score >= 4 ? '#fff7ed' : '#fefce8';
  return `<span style="display:inline-block;font-size:12px;font-weight:700;color:${color};background:${background};border-radius:4px;padding:2px 8px;">${score}/5</span>`;
};

const cards = significant.map((row) => `
  <tr>
    <td style="padding:18px 0;border-bottom:1px solid #f1f5f9;">
      <div style="margin-bottom:6px;">
        ${badge(Number(row.significance))}
        <span style="font-size:12px;color:#64748b;text-transform:uppercase;letter-spacing:.04em;margin-left:8px;">${escapeHtml(row.category)}</span>
      </div>
      <a href="${escapeHtml(row.url)}" style="font-size:16px;font-weight:600;color:#0f172a;text-decoration:none;">${escapeHtml(row.headline)}</a>
      <div style="font-size:13px;color:#64748b;margin:4px 0 8px;">${escapeHtml(row.name)}</div>
      <div style="font-size:14px;color:#334155;line-height:1.5;">${escapeHtml(row.summary)}</div>
      ${row.why_it_matters ? `<div style="font-size:14px;color:#0f172a;line-height:1.5;margin-top:8px;"><strong>Why it matters:</strong> ${escapeHtml(row.why_it_matters)}</div>` : ''}
      <div style="font-size:12px;color:#94a3b8;margin-top:8px;">+${Number(row.added_count) || 0} lines added &middot; -${Number(row.removed_count) || 0} lines removed</div>
    </td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:24px;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <table align="center" cellpadding="0" cellspacing="0" width="100%" style="max-width:640px;background:#ffffff;border:1px solid #e2e8f0;border-radius:10px;margin:0 auto;">
    <tr>
      <td style="padding:24px;background:#0f172a;border-radius:10px 10px 0 0;">
        <div style="font-size:19px;font-weight:700;color:#ffffff;">Competitor change digest</div>
        <div style="font-size:13px;color:#94a3b8;margin-top:4px;">${significant.length} notable change${significant.length === 1 ? '' : 's'} across ${results.length} tracked page${results.length === 1 ? '' : 's'}</div>
      </td>
    </tr>
    <tr>
      <td style="padding:8px 24px 24px;">
        <table cellpadding="0" cellspacing="0" width="100%">${cards}</table>
        ${failed.length ? `<div style="font-size:12px;color:#94a3b8;padding-top:16px;">${failed.length} page${failed.length === 1 ? ' was' : 's were'} unreachable this run.</div>` : ''}
      </td>
    </tr>
  </table>
</body>
</html>`;

return [{
  json: {
    hasChanges: true,
    checked: results.length,
    significant: significant.length,
    subject: `${significant.length} competitor change${significant.length === 1 ? '' : 's'} worth reading`,
    html,
  },
}];
